package com.bqsqwad.heartbreakhealer.feature.entertainment

internal object StoryLibraryBatch115 {
    val stories = listOf(
        StorySeries(
            id = "the_archive_of_winter_sunshine",
            title = "The Archive of Winter Sunshine",
            tagline = "A school photography club preserves memories of changing seasons while learning to record places with care.",
            parts = listOf(
                StoryPart(1, "The Empty Display", listOf("The school corridor had a display case reserved for seasonal photographs, but its winter section was empty. The photography club had plenty of pictures, yet none had captions or dates reliable enough for an exhibition.", "Nneka suggested building an archive instead of choosing images at random. Their teacher agreed, provided the students obtained permission from anyone clearly shown in a photograph.", "They began by gathering pictures of the school garden, the sports field, and the public square.")),
                StoryPart(2, "Dates and Details", listOf("The first photographs showed the same garden at different times of year. Some files had dates, while others had only names such as 'IMG final' and 'best one'.", "The club compared the pictures with school calendars and asked the photographer when the dates were uncertain. They labelled estimates as estimates rather than presenting them as facts.", "Nneka created a spreadsheet with the image title, date confidence, photographer, and permission status.")),
                StoryPart(3, "A Face in the Background", listOf("While reviewing a photograph of the garden, the students noticed a visitor in the background. The picture was attractive, but the visitor had not agreed to appear in the exhibition.", "The teacher helped them crop the image so the person was no longer identifiable. They also reviewed the rest of the collection for similar issues.", "The club added a rule: a beautiful photograph was not automatically suitable for public display.")),
                StoryPart(4, "The Sunshine Question", listOf("A younger student asked why winter photographs sometimes looked brighter than summer photographs. Nneka proposed a small display explaining that light, clouds, camera settings, and the time of day all affect an image.", "The science teacher checked the explanation and helped distinguish weather conditions from the way a camera records light.", "The club added a note inviting visitors to compare the photographs without assuming that brightness alone described the weather.")),
                StoryPart(5, "The Forgotten Camera", listOf("A retired teacher donated an old camera and a notebook of photographs. The notebook included a list of school events but did not explain who had taken every picture.", "The club contacted the school archive volunteer, who recognised several events and helped identify the photographer for some images. Unconfirmed photographs stayed out of the public display.", "The students learned that preserving a memory also meant preserving what was known—and what was not known—about it.")),
                StoryPart(6, "A Room for Captions", listOf("The club held a caption-writing afternoon. Students were asked to describe what could actually be seen rather than inventing stories about people or events.", "One caption said, 'Everyone was excited.' The teacher asked how the photograph proved that. The students changed it to describe the colourful decorations and crowded tables.", "The revised captions were more accurate and still gave visitors plenty to imagine.")),
                StoryPart(7, "The Display Goes Up", listOf("The winter photographs were printed and placed in the display case. Each included a date, a short description, and the photographer's credit where known.", "The club arranged the images so visitors could compare the garden across several years. A small note explained that some dates were approximate.", "Students stopped in the corridor to point out changes they remembered, from a new bench to a tree that had grown taller.")),
                StoryPart(8, "A Different Kind of Weather", listOf("A storm damaged a section of the garden fence, so the club postponed its planned outdoor photography session. The grounds team secured the area and asked students to keep away until repairs were complete.", "Nneka suggested photographing the garden from the corridor window instead. The teacher approved the idea because it did not interfere with the repair work.", "The resulting images showed clouds clearing above the garden and the work crew preparing the space for restoration.")),
                StoryPart(9, "Voices from the Past", listOf("The archive volunteer visited the club and shared a few approved memories about the older photographs. She explained how the school garden had once been a bare patch of ground.", "The students recorded her comments with permission and labelled them as recollections, not official records. They placed them beside the images they referred to.", "Visitors enjoyed seeing how the same place could hold different memories for different generations.")),
                StoryPart(10, "The Light Returns", listOf("At the end of winter, the club opened its completed archive to families. The display included photographs, carefully checked captions, and a small guide explaining how the collection had been prepared.", "Nneka added a final page listing the club's rules for future photographers: ask permission, protect private details, record dates honestly, and keep original files safely stored.", "When spring sunlight reached the corridor, the photographs seemed to change again. The archive was ready for another season, and the students knew how to care for the stories inside it."))
            )
        )
    )
}
